{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "In six cancer patients, niraparib given as a 300 mg oral dose with a 14C-IV reference had an absolute oral bioavailability of 72.7% (90% CI 61.69–83.40), well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Flecainide absolute bioavailability averaged 70% (range 60–86%) in ten healthy subjects after IV and oral dosing, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Tasimelteon absolute bioavailability was 38% (90% CI 27–54%) in 14 healthy volunteers after a 20-mg oral capsule versus 2-mg IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer absolute oral bioavailability measurements in humans (niraparib 72.7%, flecainide 70%, tasimelteon 38%, sertindole ~75%, didanosine 43%, papaverine 29%) all exceed the 20% threshold; no strongest numeric record supports low bioavailability.",
  "evidence_gaps": [
    "Qualitative 'high/excellent' records for molecules 4, 9, and 10 lack numeric F values and were not used as quantitative support.",
    "Didanosine has some pediatric/fed/formulation-specific values below 20% (e.g., C08, C17, C60), but the strongest adult IV-referenced record is 43%.",
    "Papaverine sustained-release absolute F values (22–29%) are close to the 20% threshold, adding minor uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

